package main

import "fmt"

func main() {
	var s *string
	fmt.Println(s == nil)

	var i interface{}
	fmt.Println(i == nil)

	i = s
	fmt.Println(i == nil)
}

package main

import "fmt"

type MyStruct struct {
	Value string
}

type MyInterface interface {
	GetValue() string
}

func (m *MyStruct) GetValue() string {
	return m.Value
}

func ToNil(obj MyInterface) {
	if obj == nil {
		fmt.Printf("obj = nil")
		return
	}
	obj = nil
}

func main() {
	myStruct := &MyStruct{Value: "test"}

	ToNil(myStruct)
	fmt.Printf("myStruct: %+v \n", myStruct)

	myStruct = nil

	ToNil(myStruct)
	fmt.Printf("myStruct: %+v \n", myStruct)
}

package main

import (
	"fmt"
	"reflect"
)

func foo(bar any) {
	if bar == nil {
		fmt.Println("nil interface")
	} else if reflect.ValueOf(bar).IsNil() {
		fmt.Println("non-nil interface with nil value")
	}

	v, ok := bar.(int)
	fmt.Println(v, ok)
}

func main() {
	foo(nil)
	var p *int
	foo(p)
	foo(42)
}

package main

import "fmt"

type errorString struct {
	code int
}

func (e *errorString) Error() string {
	return fmt.Sprintf("error message: %d", e.code)
}

func checkError(err error) bool {
	return err != nil
}

func main() {
	var e *errorString
	if checkError(e) {
		fmt.Println(1, e)
	}
	e = new(errorString)
	if checkError(e) {
		fmt.Println(2, e)
	}
	e = nil
	if checkError(e) {
		fmt.Println(3, e)
	}
}

package main

import (
	"fmt"
)

type MyError struct{}

func (MyError) Error() string { return "MyError!" }

func errorHandler(err error) {
	if err != nil {
		fmt.Println("Error:", err)
	}
}

func main() {
	var err *MyError
	errorHandler(err)

	err = &MyError{}
	errorHandler(err)
}
